import validator from 'validator';

export default class Login {
    constructor(formClass) {
        this.form = document.querySelector(formClass);
    }

    init() {
        this.events();
    }

    events() {
        if(!this.form) return;
        this.form.addEventListener('submit', e => {
            e.preventDefault();
            this.validate(e);
        });
    }

    validate(e) {
        const el = e.target;
        const emailInput = el.querySelector('input[name="email"]');
        const passwordInput = el.querySelector('input[name="password"]');
        let error = false;

        this.limpaErros();

        if(!validator.isEmail(emailInput.value)) {
            this.criaErro(emailInput, 'E-mail inválido');
            error = true;
        }

        if(passwordInput.value.length < 7 || passwordInput.value.length > 25) {
            this.criaErro(passwordInput,'Senha precisa conter entre 7 e 25 caracteres');
            error = true;
        }

        if(!error) {
            HTMLFormElement.prototype.submit.call(el);
        }
    }

    criaErro(campo, msg) {
        const small = document.createElement('small');
        small.innerHTML = msg;
        small.classList.add('error-text-animated', 'error-text');
        campo.insertAdjacentElement('afterend', small);
    }

    limpaErros() {
        for(let errorText of this.form.querySelectorAll('.error-text')) errorText.remove();
    }
}